            if not still:
                messages.append({"role": "user", "content": results + note})
                for rec in decided.values():
                    rec["turns"] = turn + 1
                return finish("")
            if any(r.get("is_error") is None for r in results) and len(still) < len(pending):
                note = note + [{"type": "text", "text": f"Still open: {still}."}]
            messages.append({"role": "user", "content": results + note})

    return finish("verification budget exhausted without official confirmation")


