function docIcon(t) { const m = DOC_ICONS.find(([re]) => re.test(t)); return m ? m[1] : "📄"; }
function checkText(c) { return c.check_needed.map(k => L().checks[k] || k).join(", "); }
function headlineSpeech(r) { return L().sayHeadline(rupee(r.total_missing_inr_per_year)) + " " + r.summary; }
function renderResults(r, say) {
  lastResult = r; show("s-results");
  $("amt").textContent = rupee(r.total_missing_inr_per_year);
  const more = r.likely_extra_inr_per_year || 0;
  $("more").classList.toggle("hidden", !more); $("more").textContent = more ? L().moreIf(rupee(more)) : "";
  const box = $("cards"); box.innerHTML = "";
  if (!r.cards.length) { const p = document.createElement("div"); p.className = "card scheme"; p.textContent = L().none; box.appendChild(p); }
  r.cards.forEach(c => {
    const el = document.createElement("article"); el.className = "card scheme";
    const top = document.createElement("div"); top.className = "scheme-top";
    const em = document.createElement("div"); em.className = "emoji"; em.textContent = c.emoji;
    const head = document.createElement("div"); head.style.flex = "1";
    const h3 = document.createElement("h3"); h3.textContent = c.name;
    const who = document.createElement("div"); who.className = "who"; who.textContent = `${L().forWho} ${c.member}`;
    head.append(h3, who); top.append(em, head); el.appendChild(top);
    const money = c.annual_value_inr ? `${rupee(c.annual_value_inr)} ${L().perYear}` : "";
    if (money) { const m = document.createElement("div"); m.className = "money" + (c.counts_toward_total ? "" : " soft"); m.textContent = money; el.appendChild(m); }
    const badge = document.createElement("div");
    if (c.already_receiving) { badge.className = "badge have"; badge.textContent = L().have; }
    else if (c.verification === "confirmed") { badge.className = "badge ok"; badge.textContent = L().confirmed; }
    else { badge.className = "badge check"; badge.textContent = `⚠️ ${L().check} ${checkText(c)}`; }
    el.appendChild(badge);
    const ben = document.createElement("div"); ben.className = "benefit"; ben.textContent = c.benefit; el.appendChild(ben);
    if (c.documents.length) {
      const docs = document.createElement("div"); docs.className = "docs"; docs.setAttribute("aria-label", L().docs);
      c.documents.forEach(t => { const d = document.createElement("span"); d.className = "doc";
        const e = document.createElement("span"); e.className = "e"; e.textContent = docIcon(t); d.append(e, document.createTextNode(t)); docs.appendChild(d); });
      el.appendChild(docs);
    }
    const actions = document.createElement("div"); actions.className = "actions";
    const ap = document.createElement("button"); ap.className = "apply"; ap.textContent = "📍 " + L().whereApply;
    const say = document.createElement("button"); say.className = "speak"; say.textContent = "🔊"; say.setAttribute("aria-label", "read aloud");
    actions.append(ap, say); el.appendChild(actions);
    const where = document.createElement("div"); where.className = "where hidden";
    where.appendChild(document.createTextNode(c.where_to_apply));
    const url = /^https?:/.test(c.apply_url || "") ? c.apply_url : c.official_url;
    if (url) { const a = document.createElement("a"); a.href = url; a.target = "_blank"; a.rel = "noopener"; a.textContent = L().openSite; where.appendChild(a); }
    el.appendChild(where);
    ap.onclick = () => where.classList.toggle("hidden");
    const src = document.createElement("a"); src.className = "src"; src.href = c.official_url; src.target = "_blank"; src.rel = "noopener";
    src.textContent = L().source; el.appendChild(src);
    say.onclick = () => speak(L().sayCard(c, money, c.verification === "confirmed" ? "" : `${L().check} ${checkText(c)}. `));
    box.appendChild(el);
  });
  $("answer").classList.add("hidden");
  if (say) speak(headlineSpeech(r));
}
$("sayHeadline").onclick = () => lastResult && speak(headlineSpeech(lastResult));
$("askBtn").onclick = () => listen(async (text) => {
  try {
    const r = await api(`/api/households/${hid}/ask`, { lang, text });
    $("answer").textContent = r.answer; $("answer").classList.remove("hidden"); speak(r.answer);

